def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    """Count integers in [start, finish] ending in s with every digit <= limit."""
    suffix = int(s)
    scale = 10 ** len(s)

    if any(int(digit) > limit for digit in s):
        return 0

    def count_up_to(bound: int) -> int:
        if bound < suffix:
            return 0

        maximum_prefix = (bound - suffix) // scale
        digits = str(maximum_prefix)
        count = 0

        for index, char in enumerate(digits):
            digit = int(char)
            remaining = len(digits) - index - 1
            count += min(digit, limit + 1) * (limit + 1) ** remaining
            if digit > limit:
                return count

        return count + 1

    return count_up_to(finish) - count_up_to(start - 1)

