MOD = 998244353


def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """Given a grid of fixed digits and '?', count proper 3-colorings modulo MOD."""
    # Use the shorter dimension as the transfer width.
    if W <= H:
        rows = [tuple(row) for row in grid]
    else:
        rows = [tuple(grid[r][c] for r in range(H)) for c in range(W)]
    width = len(rows[0])

    # A row state is a horizontally proper assignment satisfying that row's clues.
    row_states = []
    for row in rows:
        choices = []
        for ch in row:
            if ch == "?":
                choices.append((0, 1, 2))
            else:
                choices.append((int(ch) - 1,))
        states = []

        def build(pos, prev, acc):
            if pos == width:
                states.append(tuple(acc))
                return
            for color in choices[pos]:
                if color != prev:
                    acc.append(color)
                    build(pos + 1, color, acc)
                    acc.pop()

        build(0, -1, [])
        if not states:
            return 0
        row_states.append(states)

    dp = {state: 1 for state in row_states[0]}
    for i in range(1, len(row_states)):
        choices = []
        for ch in rows[i]:
            choices.append((0, 1, 2) if ch == "?" else (int(ch) - 1,))

        nxt = {}
        for above, ways in dp.items():
            # Generate only states in the next row that differ vertically
            # and remain horizontally proper.
            acc = []

            def build_next(pos, prev):
                if pos == width:
                    state = tuple(acc)
                    nxt[state] = (nxt.get(state, 0) + ways) % MOD
                    return
                for color in choices[pos]:
                    if color != above[pos] and color != prev:
                        acc.append(color)
                        build_next(pos + 1, color)
                        acc.pop()

            build_next(0, -1)
        dp = nxt
        if not dp:
            return 0
    return sum(dp.values()) % MOD

