from functools import lru_cache
from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """Determine whether available rectangular tiles can exactly cover the grid."""
    if n != len(tiles):
        n = min(n, len(tiles))
    area = h * w
    if sum(a * b for a, b in tiles[:n]) < area:
        return False

    # The grid is represented by one bit per cell.
    full = (1 << area) - 1
    placements = []
    for a, b in tiles[:n]:
        options = set()
        for height, width in {(a, b), (b, a)}:
            if height <= h and width <= w:
                for row in range(h - height + 1):
                    for col in range(w - width + 1):
                        bits = 0
                        row_bits = (1 << width) - 1
                        for rr in range(row, row + height):
                            bits |= row_bits << (rr * w + col)
                        options.add((height, width, row, col, bits))
        placements.append(options)

    tile_areas = [a * b for a, b in tiles[:n]]

    @lru_cache(None)
    def search(occupied: int, used: int) -> bool:
        if occupied == full:
            return True
        remaining = area - occupied.bit_count()
        if sum(tile_areas[i] for i in range(n) if not (used >> i) & 1) < remaining:
            return False

        # The first uncovered cell must be the top-left cell of the tile that
        # covers it: any cell above or to its left has already been filled.
        missing = full ^ occupied
        first = (missing & -missing).bit_length() - 1
        row, col = divmod(first, w)

        tried = set()
        for i in range(n):
            if (used >> i) & 1:
                continue
            shape = tuple(sorted(tiles[i]))
            if shape in tried:
                continue
            tried.add(shape)
            for height, width, r, c, bits in placements[i]:
                if r == row and c == col and not (bits & occupied):
                    if search(occupied | bits, used | (1 << i)):
                        return True
        return False

    return search(0, 0)

