def can_color_all_points(n: int, k: int) -> bool:
    """Return whether alternating reflection constraints allow all points to be colored.

    Reflection across the axis through point p maps point x to (2*p - x) mod n.
    A legal coloring step either completes the sole unmatched reflection pair
    for the active axis, or adds a fixed point when the colored set is already
    symmetric about that axis.
    """
    axes = (0, k)

    def fixed_points(p: int):
        if n % 2:
            return (p,)
        return (p, (p + n // 2) % n)

    # A one-point set can be symmetric about Alice's axis only at a fixed point.
    pending = []
    for first in fixed_points(0):
        black = bytearray(n)
        black[first] = 1
        unmatched = [set(), set()]
        for idx, p in enumerate(axes):
            mate = (2 * p - first) % n
            if mate != first and not black[mate]:
                unmatched[idx].add(first)
        pending.append((black, unmatched, 1))

    while pending:
        black, unmatched, count = pending.pop()
        while count < n:
            idx = count % 2
            p = axes[idx]
            open_pairs = unmatched[idx]

            if len(open_pairs) > 1:
                break
            if open_pairs:
                y = next(iter(open_pairs))
                choices = ((2 * p - y) % n,)
            else:
                choices = tuple(x for x in fixed_points(p) if not black[x])
                if not choices:
                    break

            if len(choices) > 1:
                for x in choices[1:]:
                    next_black = black.copy()
                    next_black[x] = 1
                    next_unmatched = [unmatched[0].copy(), unmatched[1].copy()]
                    for j, axis in enumerate(axes):
                        mate = (2 * axis - x) % n
                        if mate != x:
                            if next_black[mate]:
                                next_unmatched[j].discard(mate)
                            else:
                                next_unmatched[j].add(x)
                    pending.append((next_black, next_unmatched, count + 1))

            x = choices[0]
            black[x] = 1
            for j, axis in enumerate(axes):
                mate = (2 * axis - x) % n
                if mate != x:
                    if black[mate]:
                        unmatched[j].discard(mate)
                    else:
                        unmatched[j].add(x)
            count += 1

        if count == n:
            return True

    return False

