def count_good_sequences(N: int, M: int) -> int:
    """ Count the number of length-M sequences of positive integers whose product is a "good integer" not exceeding N.

    A positive integer n is called a "good integer" if and only if the sum of its positive divisors is divisible by 3.

    The result should be returned modulo 998244353.

    Args:
        N: Upper bound for the product of elements in the sequence (1 <= N <= 10^10)
        M: Length of the sequences (1 <= M <= 10^5)

    Returns:
        The number of valid sequences modulo 998244353

    >>> count_good_sequences(10, 1)
    5
    >>> count_good_sequences(4, 2)
    2
    >>> count_good_sequences(370, 907)
    221764640
    """
    mod = 998244353
    if N <= 1:
        return 0

    max_exp = N.bit_length()
    weights = [1] * (max_exp + 1)
    for e in range(1, max_exp + 1):
        weights[e] = weights[e - 1] * (M + e - 1) % mod
        weights[e] = weights[e] * pow(e, mod - 2, mod) % mod

    if N <= 1_000_000:
        spf = [0] * (N + 1)
        primes = []
        for x in range(2, N + 1):
            if not spf[x]:
                spf[x] = x
                primes.append(x)
            for p in primes:
                if p > spf[x] or p * x > N:
                    break
                spf[p * x] = p

        total = 0
        for n in range(2, N + 1):
            t = n
            w = 1
            good = False
            while t > 1:
                p = spf[t]
                e = 0
                while t % p == 0:
                    t //= p
                    e += 1
                w = w * weights[e] % mod
                if p != 3:
                    if p % 3 == 1:
                        good |= (e + 1) % 3 == 0
                    else:
                        good |= e % 2 == 1
            if good:
                total += w
        return total % mod

    limit = int(N ** 0.5)
    sieve = bytearray(b"\x01") * (limit + 1)
    sieve[0:2] = b"\x00\x00"
    primes = []
    for p in range(2, limit + 1):
        if sieve[p]:
            primes.append(p)
            if p * p <= limit:
                sieve[p * p:limit + 1:p] = b"\x00" * (((limit - p * p) // p) + 1)

    total = 0

    def visit(start, remaining, weight, good):
        nonlocal total
        if good:
            total = (total + weight) % mod
        for i in range(start, len(primes)):
            p = primes[i]
            if p > remaining:
                break
            q = p
            e = 1
            while q <= remaining:
                if p == 3:
                    local_good = False
                elif p % 3 == 1:
                    local_good = (e + 1) % 3 == 0
                else:
                    local_good = e % 2 == 1
                visit(i + 1, remaining // q, weight * weights[e] % mod, good or local_good)
                if q > remaining // p:
                    break
                q *= p
                e += 1

    visit(0, N, 1, False)

    # Every remaining n has a unique factorization n=m*q with q prime > sqrt(N)
    # and m <= sqrt(N). Sum q by residue class after a segmented prime sieve.
    query_values = sorted({N // m for m in range(1, limit + 1) if N // m > limit})
    prime_prefix = {}
    query_index = 0
    count1 = count2 = 0
    block_size = 100_000
    lo = limit + 1
    while lo <= N:
        hi = min(N + 1, lo + block_size)
        flags = bytearray(b"\x01") * (hi - lo)
        for p in primes:
            if p * p >= hi:
                break
            first = max(p * p, ((lo + p - 1) // p) * p)
            if first < hi:
                flags[first - lo:hi - lo:p] = b"\x00" * (((hi - 1 - first) // p) + 1)
        for offset, prime_flag in enumerate(flags):
            value = lo + offset
            if prime_flag:
                if value % 3 == 1:
                    count1 += 1
                elif value % 3 == 2:
                    count2 += 1
            while query_index < len(query_values) and query_values[query_index] == value:
                prime_prefix[value] = (count1, count2)
                query_index += 1
        lo = hi

    small_spf = [0] * (limit + 1)
    small_primes = []
    for x in range(2, limit + 1):
        if not small_spf[x]:
            small_spf[x] = x
            small_primes.append(x)
        for p in small_primes:
            if p > small_spf[x] or p * x > limit:
                break
            small_spf[p * x] = p

    tail = 0
    for m in range(1, limit + 1):
        t = m
        w = 1
        good = False
        while t > 1:
            p = small_spf[t]
            e = 0
            while t % p == 0:
                t //= p
                e += 1
            w = w * weights[e] % mod
            if p != 3:
                if p % 3 == 1:
                    good |= (e + 1) % 3 == 0
                else:
                    good |= e % 2 == 1
        upper = N // m
        c1, c2 = prime_prefix.get(upper, (0, 0))
        tail += w * M * (c1 + c2 if good else c2)

    return (total + tail) % mod

