from typing import List


MOD = 998244353


def count_strings_by_lcs_length(n: int, m: int, s: str) -> List[int]:
    """Given a lowercase English string s of length n and integer m,
    count length-m lowercase strings by their LCS length with s.
    """
    # A DP state is the LCS row for all prefixes of s after reading the
    # current prefix of the generated string. There are at most 2**n such
    # rows: adjacent entries can differ only by zero or one.
    chars = set(s)
    other_count = 26 - len(chars)
    other_char = next((chr(c) for c in range(ord("a"), ord("z") + 1)
                       if chr(c) not in chars), None)

    dp = {(0,) * (n + 1): 1}
    for _ in range(m):
        nxt = {}
        for row, ways in dp.items():
            # Characters appearing in s each have their own transition.
            for ch in chars:
                updated = [0] * (n + 1)
                for i in range(1, n + 1):
                    updated[i] = max(
                        row[i],
                        updated[i - 1],
                        row[i - 1] + (s[i - 1] == ch),
                    )
                state = tuple(updated)
                nxt[state] = (nxt.get(state, 0) + ways) % MOD

            # Every alphabet character absent from s induces the same row.
            if other_count:
                updated = [0] * (n + 1)
                for i in range(1, n + 1):
                    updated[i] = max(row[i], updated[i - 1])
                state = tuple(updated)
                nxt[state] = (nxt.get(state, 0) + ways * other_count) % MOD
        dp = nxt

    ans = [0] * (n + 1)
    for row, ways in dp.items():
        ans[row[n]] = (ans[row[n]] + ways) % MOD
    return ans

