from functools import lru_cache


def count_beautiful_integers(low: int, high: int, k: int) -> int:
    """Count integers in [low, high] with equal even/odd digit counts divisible by k."""
    def count_up_to(limit: int) -> int:
        if limit <= 0:
            return 0

        digits = tuple(map(int, str(limit)))
        n = len(digits)

        @lru_cache(None)
        def dp(pos: int, remainder: int, balance: int, tight: bool) -> int:
            if pos == n:
                return int(remainder == 0 and balance == 0)

            max_digit = digits[pos] if tight else 9
            total = 0
            for digit in range(0 if pos else 1, max_digit + 1):
                next_tight = tight and digit == max_digit
                next_balance = balance + (1 if digit % 2 == 0 else -1)
                total += dp(
                    pos + 1,
                    (remainder * 10 + digit) % k,
                    next_balance,
                    next_tight,
                )
            return total

        total = 0
        # Count shorter positive lengths independently, with no leading zero.
        for length in range(1, n):
            shorter_digits = (9,) * length

            @lru_cache(None)
            def shorter_dp(pos: int, remainder: int, balance: int) -> int:
                if pos == length:
                    return int(remainder == 0 and balance == 0)
                result = 0
                for digit in range(1 if pos == 0 else 0, 10):
                    result += shorter_dp(
                        pos + 1,
                        (remainder * 10 + digit) % k,
                        balance + (1 if digit % 2 == 0 else -1),
                    )
                return result

            total += shorter_dp(0, 0, 0)

        return total + dp(0, 0, 0, True)

    return count_up_to(high) - count_up_to(low - 1)

from functools import lru_cache


def count_beautiful_integers(low: int, high: int, k: int) -> int:
    """ Count the number of beautiful integers in the range [low, high].

    A number is beautiful if it meets both conditions:
    1. The count of even digits equals the count of odd digits
    2. The number is divisible by k

    Args:
        low: Lower bound of the range (inclusive), 0 < low <= high <= 10^9
        high: Upper bound of the range (inclusive)
        k: Divisor to check, 0 < k <= 20

    Returns:
        The count of beautiful integers in the given range
    """
    def count_up_to(bound: int) -> int:
        if bound <= 0:
            return 0

        digits = tuple(map(int, str(bound)))

        @lru_cache(None)
        def dp(pos: int, remainder: int, balance: int, started: bool, tight: bool) -> int:
            if pos == len(digits):
                return int(started and balance == 0 and remainder == 0)

            limit = digits[pos] if tight else 9
            total = 0
            for digit in range(limit + 1):
                next_tight = tight and digit == limit
                if not started and digit == 0:
                    total += dp(pos + 1, 0, 0, False, next_tight)
                else:
                    next_balance = balance + (1 if digit % 2 == 0 else -1)
                    next_remainder = (remainder * 10 + digit) % k
                    total += dp(pos + 1, next_remainder, next_balance, True, next_tight)
            return total

        return dp(0, 0, 0, False, True)

    return count_up_to(high) - count_up_to(low - 1)

