from collections import deque


def min_operations_to_rearrange(n: int, s: str, t: str) -> int:
    """Find the shortest sequence of pair moves from s to t, or return -1."""
    if len(s) != n or len(t) != n or s.count("B") != t.count("B"):
        return -1

    start = s + "__"
    goal = t + "__"
    if start == goal:
        return 0

    distance = {start: 0}
    queue = deque([start])

    while queue:
        state = queue.popleft()
        next_distance = distance[state] + 1
        holes = [i for i, value in enumerate(state) if value == "_"]

        for i in range(n + 1):
            if state[i] == "_" or state[i + 1] == "_":
                continue
            first, second = state[i], state[i + 1]
            # Place the selected stones into the empty cells in left-to-right
            # order; their order is preserved by the move.
            for left, right in (holes,):
                updated = list(state)
                updated[i] = updated[i + 1] = "_"
                updated[left] = first
                updated[right] = second
                neighbor = "".join(updated)
                if neighbor == goal:
                    return next_distance
                if neighbor not in distance:
                    distance[neighbor] = next_distance
                    queue.append(neighbor)

    return -1

