def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    """Calculate twice the area of black-painted regions inside the rectangle."""
    # The signed coloring (+1 for black, -1 for white) is periodic every
    # four units in both directions. Integrate it over one period and use
    # inclusion-exclusion on a two-dimensional prefix integral.
    def clip(poly, k, keep_below):
        if not poly:
            return []
        out = []
        for p, q in zip(poly, poly[1:] + poly[:1]):
            fp = p[0] + p[1] - k
            fq = q[0] + q[1] - k
            inp = fp <= 0 if keep_below else fp >= 0
            inq = fq <= 0 if keep_below else fq >= 0
            if inp:
                out.append(p)
            if inp != inq:
                t = fp / (fp - fq)
                out.append((p[0] + t * (q[0] - p[0]),
                            p[1] + t * (q[1] - p[1])))
        return out

    def area(poly):
        return abs(sum(p[0] * q[1] - q[0] * p[1]
                       for p, q in zip(poly, poly[1:] + poly[:1]))) / 2 if poly else 0

    def partial(x, y):
        # Signed area in [0,x] x [0,y], with x,y in [0,4].
        total = 0
        for i in range(4):
            for j in range(4):
                x0, x1 = max(0, i), min(x, i + 1)
                y0, y1 = max(0, j), min(y, j + 1)
                if x0 >= x1 or y0 >= y1:
                    continue
                poly = [(x0,y0),(x1,y0),(x1,y1),(x0,y1)]
                sign = -1 if (i + j // 2 + (i + j) // 2) % 2 else 1
                # A diagonal crosses the cell exactly when i+j is odd.
                if (i + j) % 2:
                    k = i + j + 1
                    lo = area(clip(poly, k, True))
                    ar = (x1-x0)*(y1-y0)
                    total += sign * (2*lo-ar)
                else:
                    total += sign * (x1-x0)*(y1-y0)
        return total

    def prefix(x, y):
        qx, rx = divmod(x, 4)
        qy, ry = divmod(y, 4)
        tile = partial(4, 4)
        return qx*qy*tile + qx*partial(4, ry) + qy*partial(rx, 4) + partial(rx, ry)

    signed = prefix(C,D) - prefix(A,D) - prefix(C,B) + prefix(A,B)
    return int(round((C-A)*(D-B) + signed))

