    """Find the minimum number of moves between tiles on the coordinate plane."""
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K

    def is_h(i, j):
        return (i - j) % 2 == 0

    sk = (S_y % K) if is_h(si, sj) else (S_x % K)
    tk = (T_y % K) if is_h(ti, tj) else (T_x % K)
    start, target = (si, sj, sk), (ti, tj, tk)
    if start == target:
        return 0

    dx, dy = abs(ti - si), abs(tj - sj)
    from heapq import heappop, heappush

    if dx + dy <= 30 and K <= 300:
        from collections import deque

        def exact_neighbors(state):
            i, j, k = state
            out = []
            if is_h(i, j):
                if k:
                    out.append((i, j, k - 1))
                if k + 1 < K:
                    out.append((i, j, k + 1))
                out.extend(((i - 1, j, K - 1), (i + 1, j, 0)))
                if k == 0:
                    out.extend((i, j - 1, x) for x in range(K))
                if k == K - 1:
                    out.extend((i, j + 1, x) for x in range(K))
            else:
                if k:
                    out.append((i, j, k - 1))
                if k + 1 < K:
                    out.append((i, j, k + 1))
                if k == 0:
                    out.extend((i - 1, j, y) for y in range(K))
                if k == K - 1:
                    out.extend((i + 1, j, y) for y in range(K))
                out.extend(((i, j - 1, K - 1), (i, j + 1, 0)))
            return out

        queue = deque([start])
        dist = {start: 0}
        while queue:
            state = queue.popleft()
            nd = dist[state] + 1
            for nxt in exact_neighbors(state):
                if nxt == target:
                    return nd
                if nxt not in dist:
                    dist[nxt] = nd
                    queue.append(nxt)

    indices = sorted({0, K - 1, sk, tk})
    index_set = set(indices)

    def local_distances(origin, bounds=None):
        oi, oj, _ = origin
        if bounds is None:
            xmin, xmax = oi - 2, oi + 2
            ymin, ymax = oj - 2, oj + 2
        else:
            xmin, xmax, ymin, ymax = bounds

        def add(out, i, j, k, cost):
            if xmin <= i <= xmax and ymin <= j <= ymax and k in index_set:
                out.append(((i, j, k), cost))

        def neighbors(state):
            i, j, k = state
            out = [((i, j, x), abs(k - x)) for x in indices if x != k]
            if is_h(i, j):
                add(out, i - 1, j, K - 1, 1)
                add(out, i + 1, j, 0, 1)
                if k == 0:
                    for x in indices:
                        add(out, i, j - 1, x, 1)
                if k == K - 1:
                    for x in indices:
                        add(out, i, j + 1, x, 1)
            else:
                if k == 0:
                    for y in indices:
                        add(out, i - 1, j, y, 1)
                if k == K - 1:
                    for y in indices:
                        add(out, i + 1, j, y, 1)
                add(out, i, j - 1, K - 1, 1)
                add(out, i, j + 1, 0, 1)
            return out

        dist = {origin: 0}
        heap = [(0, origin)]
        while heap:
            d, state = heappop(heap)
            if d != dist[state]:
                continue
            for nxt, cost in neighbors(state):
                nd = d + cost
                if nd < dist.get(nxt, 10**100):
                    dist[nxt] = nd
                    heappush(heap, (nd, nxt))
        return dist

    if dx + dy <= 30:
        bounds = (min(si, ti) - 2, max(si, ti) + 2, min(sj, tj) - 2, max(sj, tj) + 2)
        return local_distances(start, bounds).get(target, dx + dy)

    from_start = local_distances(start)
    from_target = local_distances(target)

    def diagonal_cost(a, b):
        ai, aj, _ = a
        bi, bj, bk = b
        if is_h(ai, aj) != is_h(bi, bj):
            return None
        x, y = bi - ai, bj - aj
        ax, ay = abs(x), abs(y)
        n = max(ax, ay)
        if n == 0:
            return abs(a[2] - bk)

        residual = n - min(ax, ay)
        horizontal_tiles = is_h(ai, aj)
        if K == 2 and residual:
            return 2 * min(ax, ay) + 3 * (residual // 2)

        cost = 2 * n
