            forced_sign = y if ay == n else 0
        else:
            forced_sign = x if ax == n else 0
        possible = (0,) if forced_sign > 0 else ((K - 1,) if forced_sign < 0 else (0, K - 1))
        return cost + min(abs(bk - p) for p in possible)

