def count_paths(W: int, H: int, L: int, R: int, D: int, U: int) -> int:
    """Count monotone unit-step paths through valid lattice points."""
    MOD = 998244353
    if (W + 1) * (H + 1) <= 3_000_000:
        prev = [0] * (W + 1)
        total = 0
        for y in range(H + 1):
            row = [0] * (W + 1)
            for x in range(W + 1):
                if L <= x <= R and D <= y <= U:
                    continue
                row[x] = (1 + prev[x] + (row[x - 1] if x else 0)) % MOD
                total += row[x]
            total %= MOD
            prev = row
        return total
    nmax = W + H + 5
    fact = [1] * (nmax + 1)
    for i in range(1, nmax + 1):
        fact[i] = fact[i - 1] * i % MOD
    invfact = [1] * (nmax + 1)
    invfact[nmax] = pow(fact[nmax], MOD - 2, MOD)
    for i in range(nmax, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD
    def c(n, k):
        if n < 0 or k < 0 or n < k:
            return 0
        return fact[n] * invfact[k] % MOD * invfact[n-k] % MOD
    def gsum(a, b):
        if a < 0 or b < 0:
            return 0
        return (c(a+b+4, b+2)-a-b-4) % MOD
    def fsum(a, b):
        if a < 0 or b < 0:
            return 0
        return (gsum(a,b)-(a+1)*(b+1)) % MOD
    def point(x, y):
        return (c(x+y+2, x+1)-1) % MOD
    def kernel(n, m):
        # Sum binom(d+v,d) for 0<=d<=n, 1<=v<=m.
        return (c(n+m+2, n+1)-(n+2)) % MOD
    h, k = U-D+1, H-U
    n = W-R-1
    answer = (gsum(W,D-1)-(W+1)*D) % MOD
    answer += fsum(L-1,U)-fsum(L-1,D-1)
    answer += fsum(n,h-1)
    for j in range(R+1, W+1):
        answer += point(j,D-1) * kernel(W-j,h)
    answer += fsum(W,k-1)
    left_boundary_sources = 0
    for x in range(L):
        value = point(x,U)
        left_boundary_sources += value
        answer += value * kernel(W-x,k)
    answer -= left_boundary_sources * kernel(W-L,k)
    answer += fsum(n,h+k-1)-fsum(n,h-1)-fsum(n,k-1)
    for j in range(R+1, W+1):
        answer += point(j,D-1) * (kernel(W-j,h+k)-kernel(W-j,h))
    return answer % MOD

