from functools import lru_cache


def count_beautiful_numbers(l: int, r: int) -> int:
    """Count positive integers in [l, r] whose digit product is divisible by digit sum."""
    def count_up_to(n: int) -> int:
        if n <= 0:
            return 0
        digits = tuple(map(int, str(n)))
        width = len(digits)
        total = 0

        # The digit sum is at most 9 * width. For each possible sum, track
        # the product modulo that sum. Leading zeroes are padding and do not
        # participate in the product; zeroes within the number do.
        for target in range(1, 9 * width + 1):
            @lru_cache(maxsize=None)
            def visit(pos: int, remaining: int, product_mod: int,
                      started: bool, tight: bool) -> int:
                if remaining < 0 or remaining > 9 * (width - pos):
                    return 0
                if pos == width:
                    return int(started and remaining == 0 and product_mod == 0)

                limit = digits[pos] if tight else 9
                ways = 0
                for digit in range(limit + 1):
                    next_tight = tight and digit == limit
                    if not started and digit == 0:
                        ways += visit(pos + 1, remaining, product_mod, False, next_tight)
                    else:
                        next_product = (product_mod * digit) % target
                        ways += visit(pos + 1, remaining - digit, next_product, True, next_tight)
                return ways

            total += visit(0, target, 1 % target, False, True)
        return total

    return count_up_to(r) - count_up_to(l - 1)

